// TH15 v1.00b st05.ecl.txt:1457-1470 MainSub00 (50 GirlA01 pairs, 20f apart),
// 87-96 GirlA01, 98-113 GirlA01_at, 115-135 GirlA01_at2.
// Source frame 0 = card frame ~OPENING_BUFFER; source values are used as-is.
const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;
const PAIRS: int = 50;
const PAIR_PERIOD: int = 20;

// TH15 type 8 (RICE) mapped to the shared modern catalog slot, color 6 kept.
const TH15_RICE: int = 480;

// moveVelTime mode1 = EASE_QUAD_IN, mode4 = EASE_QUAD_OUT (source rad -> BAM).
// 0.19634955 rad = 2048 BAM; mirrors use 180 - angle (32768 BAM = pi).
const TURN_LEFT_1: int = -2048;
const TURN_LEFT_2: int = 2048;
const TURN_RIGHT_1: int = 34816;
const TURN_RIGHT_2: int = 30720;

// GirlA01_at2: 10 aimed fans (etAim mode0), 3 deg spread, RICE color6.
// etCountD picks [E,N,H,L] count 1/3/5/5 and layers 1/1/3/5;
// etSpeedD picks first speed 2.2/2.2/3.2/4.2 and last speed 1.0/2.2/2.0/2.2,
// converted to the shooter's base speed + per-layer step.
// The two etExSet records are ANIM (visual) and SPEEDUP (birth presentation); omitted.
async sub girl_fire() {
    var rank: int = global(GVAR_RANK);
    var n: int = 1;
    var m: int = 1;
    var v0: fx = 2.2fx;
    var dv: fx = 0fx;
    if rank == 1 { n = 3; }
    if rank == 2 { n = 5; m = 3; v0 = 3.2fx; dv = -0.6fx; }
    if rank == 3 { n = 5; m = 5; v0 = 4.2fx; dv = -0.5fx; }
    wait(20 + rand(120)); // source: wait(20 + RAND%120)
    sh_reset(0);
    sh_sprite(0, TH15_RICE, 6);
    sh_aim(0, 1);
    sh_ring(0, 0);        // fan
    sh_count(0, n, m);
    sh_angle(0, 0deg, 3deg); // etAngle(0, 0, 0.05235988)
    sh_speed(0, v0, dv);
    for b in 0..10 {       // source $A = 10 bursts
        sh_fire(0);
        wait(10 + rand(60)); // source: wait(10 + RAND%60)
    }
}

// GirlA01_at: boxes 24/16 -> radius 12/8; async fire; polar move then two turns.
async sub girl_main(dir0: angle, turn1: angle, turn2: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    spawn girl_fire();
    move_vel(0, dir0, 3fx, EASE_LINEAR);
    move_vel(120, turn1, 2fx, EASE_QUAD_IN);
    wait(120);
    move_vel(60, turn2, 4fx, EASE_QUAD_OUT);
    loop { wait(1); } // source lives in an infinite wait loop
}

// MainSub00: per pair one F0 draw then one y draw per side, in source order.
// F0 = 0.3926991 + U*0.34906584 rad = 22.5..42.5 deg = 4096..+3641 BAM.
async sub pattern() {
    wait(OPENING_BUFFER);
    for k in 0..PAIRS {
        var u: int = rand(16384);
        var a: int = 4096 + (u * 3641) / 16384;
        var y1: fx = 64fx + ((rand(16384) as fx) / 16384) * 32fx;
        var y2: fx = 64fx + ((rand(16384) as fx) / 16384) * 32fx;
        _ = spawn_enemy(-224fx, y1, 50, 1, 1000, 0,
                        girl_main(a as angle, TURN_LEFT_1 as angle, TURN_LEFT_2 as angle));
        _ = spawn_enemy(224fx, y2, 50, 1, 1000, 0,
                        girl_main((32768 - a) as angle, TURN_RIGHT_1 as angle, TURN_RIGHT_2 as angle));
        wait(PAIR_PERIOD);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
